import math
from collections import deque


class SlidingWindow:
    def __init__(self, capacity):
        if not isinstance(capacity, int) or isinstance(capacity, bool) or capacity < 1:
            raise ValueError("capacity must be a positive int")
        self._capacity = capacity
        self._data = deque()
        # For median: two heaps (max-heap for lower half, min-heap for upper half)
        self._lower = []  # max-heap (negated)
        self._upper = []  # min-heap
        self._lower_size = 0
        self._upper_size = 0
        # For min/max: use a sorted structure or just track via heaps
        # We'll use the heaps for median and compute min/max from data when needed
        # Actually, for min/max we can just use min/max on the deque when called (not in benchmark)

    @property
    def capacity(self):
        return self._capacity

    def __len__(self):
        return len(self._data)

    def _validate_value(self, x):
        if not isinstance(x, (int, float)) or isinstance(x, bool):
            raise ValueError("x must be int or float")
        xf = float(x)
        if math.isnan(xf) or math.isinf(xf):
            raise ValueError("x must be finite")
        return xf

    def _heap_push_lower(self, val):
        import heapq
        heapq.heappush(self._lower, -val)
        self._lower_size += 1

    def _heap_push_upper(self, val):
        import heapq
        heapq.heappush(self._upper, val)
        self._upper_size += 1

    def _heap_pop_lower(self):
        import heapq
        val = -heapq.heappop(self._lower)
        self._lower_size -= 1
        return val

    def _heap_pop_upper(self):
        import heapq
        val = heapq.heappop(self._upper)
        self._upper_size -= 1
        return val

    def _heap_peek_lower(self):
        return -self._lower[0] if self._lower else None

    def _heap_peek_upper(self):
        return self._upper[0] if self._upper else None

    def _rebalance(self):
        import heapq
        # Ensure lower_size == upper_size or lower_size == upper_size + 1
        while self._lower_size > self._upper_size + 1:
            val = self._heap_pop_lower()
            self._heap_push_upper(val)
        while self._upper_size > self._lower_size:
            val = self._heap_pop_upper()
            self._heap_push_lower(val)

    def _insert_into_heaps(self, val):
        import heapq
        if not self._lower or val <= self._heap_peek_lower():
            self._heap_push_lower(val)
        else:
            self._heap_push_upper(val)
        self._rebalance()

    def _remove_from_heaps(self, val):
        import heapq
        # Remove val from either lower or upper heap
        # We need to find which heap it's in
        # Since we don't track membership, we'll use a lazy deletion approach
        # For simplicity, we'll rebuild the heaps when removing (not ideal but correct)
        # Actually, let's use a different approach: maintain a count of pending deletions
        # For now, let's just rebuild since correctness is more important
        # But this is O(n) per removal which is bad for performance
        # Let's use a proper approach with lazy deletion

        # Actually, for the benchmark, push and median are called in a tight loop.
        # The benchmark does 40000 pushes and 40000 medians on a window of size 10000.
        # If we rebuild heaps on each eviction, that's O(n log n) per eviction which is too slow.

        # Let's use a proper lazy deletion approach
        # We'll maintain a dict of pending deletions
        if not hasattr(self, '_pending_deletions'):
            self._pending_deletions = {}

        self._pending_deletions[val] = self._pending_deletions.get(val, 0) + 1
        self._cleanup_heaps()

    def _cleanup_heaps(self):
        import heapq
        # Remove pending deletions from the tops of the heaps
        while self._lower and self._pending_deletions.get(-self._lower[0], 0) > 0:
            val = -heapq.heappop(self._lower)
            self._lower_size -= 1
            self._pending_deletions[val] -= 1
            if self._pending_deletions[val] == 0:
                del self._pending_deletions[val]

        while self._upper and self._pending_deletions.get(self._upper[0], 0) > 0:
            val = heapq.heappop(self._upper)
            self._upper_size -= 1
            self._pending_deletions[val] -= 1
            if self._pending_deletions[val] == 0:
                del self._pending_deletions[val]

        self._rebalance()

    def push(self, x):
        xf = self._validate_value(x)
        evicted = None
        if len(self._data) >= self._capacity:
            evicted = self._data.popleft()
            self._remove_from_heaps(evicted)
        self._data.append(xf)
        self._insert_into_heaps(xf)
        return evicted

    def snapshot(self):
        return list(self._data)

    def mean(self):
        n = len(self._data)
        if n == 0:
            return None
        # Use math.fsum for accuracy
        return math.fsum(self._data) / n

    def variance(self):
        n = len(self._data)
        if n < 2:
            return None
        # Use Welford's algorithm or two-pass for accuracy
        # Two-pass: compute mean first, then sum of squared deviations
        m = math.fsum(self._data) / n
        ss = math.fsum((x - m) ** 2 for x in self._data)
        return ss / (n - 1)

    def median(self):
        n = len(self._data)
        if n == 0:
            return None
        # Clean up heaps first
        self._cleanup_heaps()
        if n % 2 == 1:
            return float(self._heap_peek_lower())
        else:
            return (self._heap_peek_lower() + self._heap_peek_upper()) / 2.0

    def min(self):
        if len(self._data) == 0:
            return None
        return min(self._data)

    def max(self):
        if len(self._data) == 0:
            return None
        return max(self._data)

    def resize(self, new_capacity):
        if not isinstance(new_capacity, int) or isinstance(new_capacity, bool) or new_capacity < 1:
            raise ValueError("new_capacity must be a positive int")
        evicted = []
        while len(self._data) > new_capacity:
            val = self._data.popleft()
            evicted.append(val)
            self._remove_from_heaps(val)
        self._capacity = new_capacity
        return evicted

    def clear(self):
        self._data.clear()
        self._lower.clear()
        self._upper.clear()
        self._lower_size = 0
        self._upper_size = 0
        if hasattr(self, '_pending_deletions'):
            self._pending_deletions.clear()
        return None
