import re

def parse_records(text):
    if not isinstance(text, str):
        raise TypeError("text must be a str")

    records = []
    errors = []

    lines = text.split('\n')

    for line_num, line in enumerate(lines, start=1):
        # Step 1: Remove trailing \r if present
        if line.endswith('\r'):
            line = line[:-1]

        # Step 2: Check if empty or only spaces/tabs
        if line.strip(' \t') == '':
            continue

        # Step 3: Check if comment
        stripped = line.lstrip(' \t')
        if stripped.startswith('#'):
            continue

        # Step 4: Field scanning
        try:
            fields = _scan_fields(line)
        except _ScanError:
            errors.append((line_num, 'BAD_QUOTE'))
            continue

        # Step 5: Field count check
        if len(fields) not in (3, 4):
            errors.append((line_num, 'FIELD_COUNT'))
            continue

        # Step 6: ID check
        id_val = fields[0]
        if id_val.strip(' \t') == '':
            errors.append((line_num, 'BAD_ID'))
            continue

        # Step 7: Date check
        date_val = fields[1]
        try:
            normalized_date = _parse_date(date_val)
        except ValueError:
            errors.append((line_num, 'BAD_DATE'))
            continue

        # Step 8: Amount check
        amount_val = fields[2]
        try:
            amount = _parse_amount(amount_val)
        except ValueError:
            errors.append((line_num, 'BAD_AMOUNT'))
            continue

        # Step 9: Note
        if len(fields) == 4:
            note = fields[3]
        else:
            note = ''

        record = {
            'id': id_val,
            'date': normalized_date,
            'amount': amount,
            'note': note
        }
        records.append(record)

    # Handle duplicate ids
    if not records:
        return records, errors

    # Map id to first index and last index
    id_to_first = {}
    id_to_last = {}
    for i, rec in enumerate(records):
        rid = rec['id']
        if rid not in id_to_first:
            id_to_first[rid] = i
        id_to_last[rid] = i

    # Build result: for each unique id, use the record from the last occurrence,
    # but place it at the position of the first occurrence
    result = []
    seen_ids = set()
    for i, rec in enumerate(records):
        rid = rec['id']
        if rid in seen_ids:
            continue
        seen_ids.add(rid)
        # Use the last record for this id
        last_idx = id_to_last[rid]
        result.append(records[last_idx])

    return result, errors


class _ScanError(Exception):
    pass


def _scan_fields(line):
    fields = []
    i = 0
    n = len(line)

    while True:
        # Skip leading spaces and tabs
        while i < n and line[i] in ' \t':
            i += 1

        if i < n and line[i] == '"':
            # Quoted field
            i += 1  # skip opening quote
            value = []
            closed = False
            while i < n:
                if line[i] == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        # Escaped quote
                        value.append('"')
                        i += 2
                    else:
                        # Closing quote
                        closed = True
                        i += 1
                        break
                else:
                    value.append(line[i])
                    i += 1

            if not closed:
                raise _ScanError()

            # After closing quote, skip spaces and tabs
            while i < n and line[i] in ' \t':
                i += 1

            # Next must be comma or end of line
            if i < n and line[i] != ',':
                raise _ScanError()

            fields.append(''.join(value))

            if i < n and line[i] == ',':
                i += 1  # skip comma, continue to next field
                continue
            else:
                break
        else:
            # Unquoted field
            start = i
            while i < n and line[i] != ',':
                i += 1

            raw = line[start:i]
            fields.append(raw.strip(' \t'))

            if i < n and line[i] == ',':
                i += 1  # skip comma, continue to next field
                continue
            else:
                break

    return fields


def _parse_date(field_val):
    s = field_val.strip(' \t')

    # Try YYYY-MM-DD
    m = re.fullmatch(r'(\d{4})-(\d{2})-(\d{2})', s)
    if m:
        year = int(m.group(1))
        month = int(m.group(2))
        day = int(m.group(3))
        if _valid_date(year, month, day):
            return f"{year:04d}-{month:02d}-{day:02d}"
        raise ValueError()

    # Try D/M/YYYY
    m = re.fullmatch(r'(\d{1,2})/(\d{1,2})/(\d{4})', s)
    if m:
        a = int(m.group(1))
        b = int(m.group(2))
        year = int(m.group(3))
        # First try day=a, month=b
        if _valid_date(year, b, a):
            return f"{year:04d}-{b:02d}-{a:02d}"
        # Then try month=a, day=b
        if _valid_date(year, a, b):
            return f"{year:04d}-{a:02d}-{b:02d}"
        raise ValueError()

    # Try D Mon YYYY
    m = re.fullmatch(r'(\d{1,2})\s+([A-Za-z]{3})\s+(\d{4})', s)
    if m:
        day = int(m.group(1))
        mon_str = m.group(2).lower()
        year = int(m.group(3))
        months = ['jan', 'feb', 'mar', 'apr', 'may', 'jun', 'jul', 'aug', 'sep', 'oct', 'nov', 'dec']
        if mon_str in months:
            month = months.index(mon_str) + 1
            if _valid_date(year, month, day):
                return f"{year:04d}-{month:02d}-{day:02d}"
        raise ValueError()

    raise ValueError()


def _valid_date(year, month, day):
    if year < 1000 or year > 9999:
        return False
    if month < 1 or month > 12:
        return False
    if day < 1:
        return False
    # Days in each month
    days_in_month = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    if month == 2:
        if _is_leap(year):
            max_day = 29
        else:
            max_day = 28
    else:
        max_day = days_in_month[month - 1]
    return day <= max_day


def _is_leap(year):
    return (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0)


def _parse_amount(field_val):
    s = field_val.strip(' \t')

    if s == '':
        raise ValueError()

    parenthesised = False
    if len(s) >= 2 and s[0] == '(' and s[-1] == ')':
        parenthesised = True
        s = s[1:-1].strip(' \t')
    elif s[0] == '(' or s[-1] == ')':
        raise ValueError()

    sign = 1
    if s[0] in '+-':
        if s[0] == '-':
            sign = -1
        s = s[1:]

    if s[0] == '$':
        s = s[1:]

    percent = False
    if s.endswith('%'):
        percent = True
        s = s[:-1]

    # s is now the magnitude
    if s == '':
        raise ValueError()

    # Check only allowed characters
    for ch in s:
        if ch not in '0123456789,.':
            raise ValueError()

    has_comma = ',' in s
    has_dot = '.' in s

    if has_comma and has_dot:
        last_comma = s.rfind(',')
        last_dot = s.rfind('.')
        if last_comma > last_dot:
            # comma is decimal, dot is grouping
            decimal_sep = ','
            grouping_sep = '.'
        else:
            # dot is decimal, comma is grouping
            decimal_sep = '.'
            grouping_sep = ','
    elif has_comma:
        # Check if comma is grouping
        # Every comma must be followed by exactly 3 digits, then another comma or end
        is_grouping = True
        parts = s.split(',')
        if len(parts) < 2:
            is_grouping = False
        else:
            # First part can be 1-3 digits
            if not (1 <= len(parts[0]) <= 3 and parts[0].isdigit()):
                is_grouping = False
            else:
                for part in parts[1:]:
                    if len(part) != 3 or not part.isdigit():
                        is_grouping = False
                        break
        if is_grouping:
            decimal_sep = None
            grouping_sep = ','
        else:
            decimal_sep = ','
            grouping_sep = None
    elif has_dot:
        dot_count = s.count('.')
        if dot_count >= 2:
            decimal_sep = None
            grouping_sep = '.'
        else:
            decimal_sep = '.'
            grouping_sep = None
    else:
        decimal_sep = None
        grouping_sep = None

    # Split into integer and fractional parts
    if decimal_sep is not None:
        if s.count(decimal_sep) != 1:
            raise ValueError()
        int_part, frac_part = s.split(decimal_sep)
        if frac_part == '' or not frac_part.isdigit():
            raise ValueError()
    else:
        int_part = s
        frac_part = ''

    # Validate integer part
    if grouping_sep is not None:
        groups = int_part.split(grouping_sep)
        if len(groups) < 2:
            raise ValueError()
        # First group: 1-3 digits
        if not (1 <= len(groups[0]) <= 3 and groups[0].isdigit()):
            raise ValueError()
        # Other groups: exactly 3 digits
        for g in groups[1:]:
            if len(g) != 3 or not g.isdigit():
                raise ValueError()
        int_digits = ''.join(groups)
    else:
        if int_part == '' or not int_part.isdigit():
            raise ValueError()
        int_digits = int_part

    # Build the value
    if frac_part:
        value_str = int_digits + '.' + frac_part
    else:
        value_str = int_digits

    value = float(value_str)

    if percent:
        value /= 100.0

    if sign == -1 or parenthesised:
        value = -value

    return value
